import { afterAll, describe, expect, test } from "bun:test";
import { existsSync, mkdtempSync, readFileSync, rmSync, statSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { parseHTML } from "linkedom";
import { renderContent, siteTokens } from "../site/render.ts";
import { ROUTES } from "../site/routes.ts";

// Support pages, 404 pages and site.js are generated by build.ts from the route table and the Markdown content.
// One real build for the file, run while it loads so no test timeout cuts it short.
const web = join(import.meta.dir, "..");
const SITE = "https://pubmy.belajarcarabelajar.com";
const out = mkdtempSync(join(tmpdir(), "pubmy-site-build-"));
afterAll(() => rmSync(out, { recursive: true, force: true }));
const proc = Bun.spawnSync([process.execPath, join(web, "build.ts"), out], { stdout: "pipe", stderr: "pipe" });
if (proc.exitCode !== 0) console.error(proc.stderr.toString());

const indexHtml = readFileSync(join(web, "index.html"), "utf8");
const indexCss = /<style>([\s\S]*?)<\/style>/.exec(indexHtml)![1]!;
const ROOT_RULE = /:root\{[^}]*\}/.exec(indexCss)![0];
const DARK_RULE = /@media \(prefers-color-scheme:dark\)\{:root\{[^}]*\}\}/.exec(indexCss)![0];
const VERSION = (JSON.parse(readFileSync(join(web, "package.json"), "utf8")) as { version: string }).version;

/** The file a site path is served from. */
const fileFor = (path: string) => join(out, path.endsWith("/") ? path + "index.html" : path);
const pages = ROUTES.filter((r) => r.key !== "home").flatMap((route) =>
  (["id", "en"] as const).map((lang) => ({ route, lang, path: route.path[lang], file: fileFor(route.path[lang]) })),
);
const read = (file: string) => (existsSync(file) ? readFileSync(file, "utf8") : "");

describe("the build", () => {
  test("exits 0", () => {
    expect(proc.exitCode).toBe(0);
  });

  test("writes the 16 support and not-found pages at their paths", () => {
    expect(pages).toHaveLength(16);
    expect(pages.filter((p) => !existsSync(p.file)).map((p) => p.path)).toEqual([]);
  });

  test("writes the two 404 pages where Workers look for them", () => {
    expect(existsSync(join(out, "404.html"))).toBe(true);
    expect(existsSync(join(out, "en", "404.html"))).toBe(true);
  });

  test("site.js is small, standalone and remembers the language", () => {
    const js = read(join(out, "site.js"));
    expect(js).toContain("pubmy.lang");
    expect(statSync(join(out, "site.js")).size).toBeLessThan(2048);
    expect(js).not.toMatch(/\bimport\b/);
  });

  test("wrangler serves the nearest 404.html for a missing page", () => {
    expect(readFileSync(join(web, "wrangler.jsonc"), "utf8")).toContain('"not_found_handling": "404-page"');
  });
});

for (const p of pages) {
  describe(`${p.lang} ${p.route.key} (${p.path})`, () => {
    const html = read(p.file);
    const { document } = parseHTML(html);
    const notFound = p.route.key === "notfound";

    test("is in its language with one h1, the route title", () => {
      expect(document.documentElement.getAttribute("lang")).toBe(p.lang);
      const h1 = document.querySelectorAll("h1");
      expect(h1).toHaveLength(1);
      expect(h1[0]!.textContent).toBe(p.route.title[p.lang]);
    });

    test(notFound ? "is noindex with no canonical or alternates" : "has its canonical and the id, en and x-default alternates", () => {
      const canonical = document.querySelectorAll('link[rel="canonical"]');
      const alt = [...document.querySelectorAll('link[rel="alternate"]')].map((l) => [l.getAttribute("hreflang"), l.getAttribute("href")]);
      if (notFound) {
        expect(document.querySelector('meta[name="robots"]')?.getAttribute("content")).toBe("noindex");
        expect(canonical).toHaveLength(0);
        expect(alt).toEqual([]);
      } else {
        expect(canonical).toHaveLength(1);
        expect(canonical[0]!.getAttribute("href")).toBe(SITE + p.path);
        expect(alt).toEqual([
          ["id", SITE + p.route.path.id],
          ["en", SITE + p.route.path.en],
          ["x-default", SITE + p.route.path.id],
        ]);
      }
    });

    test("loads only /site.js, with no inline script, stylesheet link or modulepreload", () => {
      const scripts = [...document.querySelectorAll("script")];
      expect(scripts.map((s) => s.getAttribute("src"))).toEqual(["/site.js"]);
      expect(scripts.filter((s) => (s.textContent ?? "").trim() !== "")).toEqual([]);
      expect(html).not.toMatch(/rel="stylesheet"|rel="modulepreload"/);
    });

    test("has one inline style carrying the colour tokens of index.html", () => {
      const styles = document.querySelectorAll("style");
      expect(styles).toHaveLength(1);
      expect(styles[0]!.textContent).toContain(ROOT_RULE);
      expect(styles[0]!.textContent).toContain(DARK_RULE);
    });

    test("has no unreplaced token", () => {
      expect(html).not.toContain("{{");
    });

    test("has the site header and footer", () => {
      expect(document.querySelector(".site-header")).not.toBeNull();
      expect(document.querySelector(".site-footer")).not.toBeNull();
    });
  });
}

describe("page content", () => {
  test("the guide pages have the FAQ section the footer links to", () => {
    for (const lang of ["id", "en"] as const) {
      const { document } = parseHTML(read(fileFor(ROUTES.find((r) => r.key === "guide")!.path[lang])));
      expect(document.querySelector("#faq")).not.toBeNull();
    }
  });

  test("the limits are filled in from the code", () => {
    expect(read(fileFor("/panduan/"))).toContain("Maksimal 10 file, masing-masing 50 MB");
    expect(read(fileFor("/en/guide/"))).toContain("Up to 10 files, 50 MB each");
  });

  test("the releases pages name the version from package.json", () => {
    expect(read(fileFor("/rilis/"))).toContain(VERSION);
    expect(read(fileFor("/en/releases/"))).toContain(VERSION);
  });

  test("every internal link resolves to a built file", () => {
    const links = pages.flatMap((p) => {
      const { document } = parseHTML(read(p.file));
      return [...document.querySelectorAll("a[href^='/']")].map((a) => ({ from: p.path, href: a.getAttribute("href")! }));
    });
    expect(links.length).toBeGreaterThan(200);
    const dead = links.filter((l) => !existsSync(fileFor(l.href.split("#")[0]!)));
    expect(dead).toEqual([]);
  });

  test("every #faq link lands on a page with id faq", () => {
    const targets = new Set(
      pages.flatMap((p) => [...parseHTML(read(p.file)).document.querySelectorAll("a[href*='#faq']")].map((a) => a.getAttribute("href")!.split("#")[0]!)),
    );
    expect([...targets].sort()).toEqual(["/en/guide/", "/panduan/"]);
    for (const t of targets) expect(parseHTML(read(fileFor(t))).document.querySelector("#faq")).not.toBeNull();
  });
});

describe("site.js behaviour", () => {
  const code = () => read(join(out, "site.js"));
  const run = (hreflang: string, storage: Pick<Storage, "setItem">) => {
    const { window, document } = parseHTML(`<!doctype html><html><body><a id="lang" href="/x/" hreflang="${hreflang}">x</a></body></html>`);
    const g = globalThis as Record<string, unknown>;
    const saved = { document: g.document, localStorage: g.localStorage };
    Object.assign(g, { document, localStorage: storage });
    try {
      new Function(code())();
      // A real click bubbles; site.js listens on the document.
      document.querySelector("#lang")!.dispatchEvent(new window.Event("click", { bubbles: true }));
    } finally {
      Object.assign(g, saved);
    }
  };

  test("a click on the language switch stores its language under pubmy.lang", () => {
    const set: [string, string][] = [];
    run("en", { setItem: (k, v) => void set.push([k, v]) });
    expect(set).toEqual([["pubmy.lang", "en"]]);
  });

  test("a value other than id or en is not stored", () => {
    const set: [string, string][] = [];
    run("fr", { setItem: (k, v) => void set.push([k, v]) });
    expect(set).toEqual([]);
  });

  test("a click on a link to the converter stores the page's own language, so /en/ pages open the converter in English", () => {
    const { window, document } = parseHTML(`<!doctype html><html lang="en"><body><a class="brand" href="/">pubmy</a><a href="/en/guide/">Guide</a></body></html>`);
    const g = globalThis as Record<string, unknown>;
    const saved = { document: g.document, localStorage: g.localStorage };
    const set: [string, string][] = [];
    Object.assign(g, { document, localStorage: { setItem: (k: string, v: string) => void set.push([k, v]) } });
    try {
      new Function(code())();
      document.querySelector('a[href="/en/guide/"]')!.dispatchEvent(new window.Event("click", { bubbles: true }));
      expect(set).toEqual([]);
      document.querySelector('a[href="/"]')!.dispatchEvent(new window.Event("click", { bubbles: true }));
      expect(set).toEqual([["pubmy.lang", "en"]]);
    } finally {
      Object.assign(g, saved);
    }
  });

  test("blocked storage does not throw out of the click", () => {
    expect(() =>
      run("id", {
        setItem: () => {
          throw new Error("blocked");
        },
      }),
    ).not.toThrow();
  });
});

describe("renderContent", () => {
  test("replaces the known tokens", () => {
    expect(renderContent("Up to {{MAX_FILES}} files, v{{VERSION}}.", { MAX_FILES: "10", VERSION: "0.2.0" })).toBe("<p>Up to 10 files, v0.2.0.</p>\n");
  });

  test("throws on an unknown token, naming it", () => {
    expect(() => renderContent("{{NOPE}}", { MAX_FILES: "10" })).toThrow(/NOPE/);
  });

  test("gives headings ids from their text, unique on the page", () => {
    const html = renderContent("## FAQ\n\n### Apakah pubmy gratis?\n\n## FAQ\n\n## `code` and **bold**", {});
    expect([...html.matchAll(/<h\d id="([^"]+)"/g)].map((m) => m[1])).toEqual(["faq", "apakah-pubmy-gratis", "faq-2", "code-and-bold"]);
  });

  test("never reuses an id the page layout already has", () => {
    expect(renderContent("## Content", {})).not.toContain('id="content"');
  });

  test("wraps every table so it scrolls on a narrow screen", () => {
    const html = renderContent("| a | b |\n|---|---|\n| 1 | 2 |", {});
    expect(html).toMatch(/^<div class="table-wrap"><table class="stack"[^>]*>[\s\S]*<\/table>\n?<\/div>/);
  });

  test("a stacked table keeps its table semantics through explicit ARIA roles", () => {
    const html = renderContent("| Format | Engine |\n|---|:-:|\n| PDF | Calibre |\n| DOCX | Pandoc |", {});
    const tags = (name: string) => [...html.matchAll(new RegExp(`<${name}(?:\\s[^>]*)?>`, "g"))].map((m) => m[0]);
    const role = (tag: string) => tag.match(/ role="([^"]*)"/)?.[1];
    expect(tags("table").map(role)).toEqual(["table"]);
    expect(tags("table")[0]).toContain('class="stack"');
    expect(tags("thead").map(role)).toEqual(["rowgroup"]);
    expect(tags("tbody").map(role)).toEqual(["rowgroup"]);
    expect(tags("tr").map(role)).toEqual(["row", "row", "row"]);
    expect(tags("th").map(role)).toEqual(["columnheader", "columnheader"]);
    const tds = tags("td");
    expect(tds.map(role)).toEqual(["cell", "cell", "cell", "cell"]);
    expect(tds.map((t) => t.match(/ data-label="([^"]*)"/)?.[1])).toEqual(["Format", "Engine", "Format", "Engine"]);
    expect(html).toContain('<div class="table-wrap">');
  });

  test("external links get rel noopener and internal links do not", () => {
    const html = renderContent("[GitHub](https://github.com/belajarcarabelajar/pubmy) [Guide](/en/guide/)", {});
    expect(html).toContain('<a href="https://github.com/belajarcarabelajar/pubmy" rel="noopener">GitHub</a>');
    expect(html).toContain('<a href="/en/guide/">Guide</a>');
  });

  test("raw HTML in the Markdown is escaped, not passed through", () => {
    expect(renderContent("<script>x</script>", {})).not.toContain("<script>");
  });

  test("siteTokens turns the code limits into the page values", () => {
    expect(siteTokens("9.9.9")).toEqual({ MAX_FILES: "10", MAX_MB: "50", RETENTION_MIN: "3", VERSION: "9.9.9" });
  });
});
